values.content:
Plan a feature flag rollout.

Feature: {{ $json.featureName }}
Description: {{ $json.featureDescription }}
Risk profile: {{ $json.riskProfile }}
User base: {{ $json.userBase || 'not specified' }}
Technical risk: {{ $json.technicalRisk || 'not specified' }}
Rollback complexity: {{ $json.rollbackComplexity.replace(/_/g,' ') }}
Target timeline: {{ $json.targetTimeline || 'not specified' }}
Dependencies: {{ $json.dependenciesOrPrereqs || 'none specified' }}
Segmentation options available: {{ $json.segmentationOptions.join(', ') || 'not specified — assume percentage-based only' }}
Business metrics to watch: {{ $json.businessMetricsToWatch.join(', ') || 'not specified' }}

Return JSON:
{"rollout_summary":"2-3 sentences on the overall rollout approach and why","stages":[{"stage_number":1,"stage_name":"","audience":"who sees the feature at this stage — be specific about %  or segment","duration":"how long to stay at this stage before proceeding","success_criteria":["specific measurable criteria to advance to next stage"],"abort_criteria":["specific measurable criteria to roll back immediately"],"metrics_to_monitor":["specific metrics for this stage"],"who_to_notify":"which teams should know this stage is starting"},"technical_checklist":["pre-rollout technical items to verify"],"rollback_plan":{"trigger_conditions":"what specifically triggers a rollback decision","rollback_steps":"how to actually roll back","rollback_time_estimate":"","data_cleanup_needed":"any cleanup needed if rolled back after partial use — or null"},"communication_plan":[{"audience":"internal_team|support|sales|customers","when":"","message":""}],"kill_switch_readiness":"specific check that a kill switch or instant-disable capability exists and is tested","post_rollout_cleanup":["steps once fully rolled out — removing flag, removing old code path"]}
